<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {authStore} from '@/stores/auth'
import {request} from '@/api/client'
import {uiText} from '@/i18n'
import {createRequestGuard} from '@/lib/requestGuard'
interface Step {id:string;title:string;description:string;url:string;completed:boolean}
const steps=ref<Step[]>([]),hidden=ref(false),focus=ref('all'),error=ref(''),busy=ref(false),guard=createRequestGuard()
const key=computed(()=>`pkb:getting-started:${authStore.state.user?.id}`)
const done=computed(()=>steps.value.filter(s=>s.completed).length)
const ordered=computed(()=>[...steps.value].sort((a,b)=>Number(b.id===focus.value)-Number(a.id===focus.value)))
function store(){try{localStorage.setItem(key.value,JSON.stringify({hidden:hidden.value,focus:focus.value}))}catch{/* This preference is optional. */}}
function toggle(){hidden.value=!hidden.value;store()}
async function load(){const run=guard.start();busy.value=true;error.value='';try{const value=await request<Step[]>('/workspace/getting-started',{signal:run.signal});if(run.current()){steps.value=value;if(value.length&&value.every(s=>s.completed))hidden.value=true}}catch(e){if(run.current())error.value=(e as Error).message}finally{if(run.current())busy.value=false}}
watch(()=>[authStore.state.user?.id,authStore.state.user?.permissions.join('|')],()=>{guard.cancel();steps.value=[];hidden.value=false;focus.value='all';try{const p=JSON.parse(localStorage.getItem(key.value)||'{}');hidden.value=p.hidden===true;if(['all','note','vocabulary','document','review'].includes(p.focus))focus.value=p.focus}catch{}if(authStore.state.user)void load()},{immediate:true})
onBeforeUnmount(()=>guard.cancel())
</script>
<template><section v-if="steps.length||error" class="getting-started panel"><header><div><p class="page-kicker">YOUR FIRST STEPS</p><h3>{{uiText('从这里开始')}} <small>{{done}} / {{steps.length}}</small></h3></div><button class="button button--ghost" :aria-expanded="!hidden" @click="toggle">{{hidden?uiText('展开引导'):uiText('暂时收起')}}</button></header><p v-if="error" role="alert">{{uiText(error)}} <button class="table-action" :disabled="busy" @click="load">{{uiText('重试')}}</button></p><template v-if="!hidden"><div class="guide-options"><label>{{uiText('这次想先做什么')}}<select v-model="focus" class="field-input" @change="store"><option value="all">{{uiText('按顺序开始')}}</option><option v-for="s in steps" :key="s.id" :value="s.id">{{uiText(s.title)}}</option></select></label><button class="table-action" :disabled="busy" @click="load">{{uiText('检查完成情况')}}</button></div><div class="guide-steps"><RouterLink v-for="(s,i) in ordered" :key="s.id" :to="s.url" :class="{complete:s.completed}"><span>{{s.completed?'✓':String(i+1).padStart(2,'0')}}</span><div><strong>{{uiText(s.title)}}</strong><p>{{uiText(s.description)}}</p><small>{{s.completed?uiText('已完成'):uiText('开始 →')}}</small></div></RouterLink></div><p class="research-hint">{{uiText('完成状态来自已保存的记录；打开页面不会被算作完成。引导可以随时收起。')}}</p></template></section></template>
<style scoped>.getting-started{padding:26px}.getting-started header{display:flex;justify-content:space-between;align-items:center}.getting-started h3{margin:8px 0}.getting-started small{font-size:12px;color:var(--muted);font-weight:400}.guide-options{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:24px 0}.guide-options label{display:flex;align-items:center;gap:16px;font-size:13px}.guide-options select{width:auto}.guide-steps{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.guide-steps a{display:flex;gap:16px;padding:20px;border:1px solid var(--line);border-radius:12px;text-decoration:none;color:var(--ink);transition:border-color .2s,background .2s}.guide-steps a:hover{border-color:var(--green);background:var(--green-soft)}.guide-steps a>span{color:var(--green);font-size:13px}.guide-steps p{font-size:13px;color:var(--muted);line-height:1.7}.guide-steps .complete{background:var(--surface-soft,var(--paper))}@media(max-width:700px){.guide-steps{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.guide-steps a{transition:none}}</style>
